let walletData=null;const preWalletRender=render,preWalletOrderCard=orderCard;
async function loadWallet(){try{walletData=await api('wallet');render()}catch(e){toast(e.message)}}
function walletPage(){return heading('Баланс твоего хозяйства.','Демонстрационный кошелёк · реальные деньги не используются.')+(!account?'<section class="panel"><button class="btn" onclick="profile()">Войти</button></section>':`<section class="panel promo"><small>ДЕМОБАЛАНС</small><h1>${walletData?money(walletData.balance_kopecks):'…'}</h1><p>Тестовые рубли нельзя обменять на настоящие. Пополнение и вывод — имитация без карты и банковского счёта.</p><div class="actions"><button class="btn" onclick="walletForm('topup')">＋ Пополнить</button><button class="btn light" onclick="walletForm('withdraw')">Вывести</button><a class="btn light" href="#orders">Оплатить заказ</a></div></section><section class="panel" style="margin-top:22px"><h3>Последние 50 операций</h3>${walletData?.entries.length?walletData.entries.map(e=>`<div class="event row"><div>${({topup:'Тестовое пополнение',withdraw:'Имитация вывода',payment:'Тестовая оплата заказа',refund:'Возврат демосредств',subscription:'Тестовая подписка',rental:'Демоаренда грядки',purchase:'Покупка в демомаркете',sale:'Продажа в демомаркете'})[e.kind]}<small>${fmt(e.created_at)}</small></div><b>${['topup','refund','sale'].includes(e.kind)?'+':'−'}${money(e.amount_kopecks)}</b></div>`).join(''):'Операций пока нет.'}</section>`)}
function walletForm(kind){const key=crypto.randomUUID();formAsync(kind==='topup'?'Тестовое пополнение':'Имитация вывода',`<p class="note">Реального перевода денег не будет.</p><label>Сумма, демо-₽<input name="amount" type="number" min="1" max="100000" step="0.01" required value="${kind==='topup'?1000:100}"></label><button class="btn">${kind==='topup'?'Добавить демосредства':'Имитировать вывод'}</button>`,async f=>{await api('wallet-'+kind,{key,amount:Math.round(Number(f.get('amount'))*100)});await loadWallet();toast('Тестовая операция выполнена')})}
async function demoPay(id){const o=opsData.orders.find(o=>o.id===id),key=crypto.randomUUID();formAsync('Тестовая оплата заказа',`<h3>${esc(o.title)} · ${money(o.price_kopecks)}</h3><p>Сумма будет списана только с демобаланса. Заказ получит отметку «Симуляция» и не является поручением выполнять реальные работы.</p><button class="btn">Оплатить демосредствами</button>`,async()=>{await api('wallet-pay',{order:id,key});await refreshCloud();await loadWallet();toast('Заказ оплачен в тестовом режиме')})}
orderCard=function(o){let html=preWalletOrderCard(o);if(o.is_simulation)html=html.replace('<h3>','<p class="demo-warning">СИМУЛЯЦИЯ · Не выполнять физические работы. Реальной оплаты нет.</p><h3>');if(o.status==='awaiting_payment'&&o.user_id===account?.id)html=html.replace('<div class="actions">',`<div class="actions"><button class="btn" onclick="demoPay('${o.id}')">Оплатить демобалансом</button>`).replace('Онлайн-оплата пока не подключена. Платная работа не запустится.','Доступна имитация оплаты. Для реальной оплаты нужен платёжный провайдер.');return html};
render=function(){if(location.hash==='#wallet'){$('#app').innerHTML=walletPage();$('#crumb').textContent='ДЕМОБАЛАНС'}else preWalletRender();const r=location.hash.slice(1);if(account&&['home','settings','orders','wallet'].includes(r))$('#app').insertAdjacentHTML('afterbegin','<div class="context-tabs"><a href="#wallet">◈ Демобаланс · пополнить / вывести</a></div>');if(r==='wallet'){userButton.textContent=account?.name||'Войти';statusBanner.textContent='Тестовый кошелёк: операции не связаны с реальными деньгами.'}};
addEventListener('hashchange',()=>{if(location.hash==='#wallet'&&account)loadWallet()});const walletRefresh=refreshCloud;refreshCloud=async function(){await walletRefresh();if(location.hash==='#wallet')await loadWallet()};render();if(account&&location.hash==='#wallet')loadWallet();
